// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkSurface) predicate.WorkSurface {
	return predicate.WorkSurface(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkSurface) predicate.WorkSurface {
	return predicate.WorkSurface(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkSurface) predicate.WorkSurface {
	return predicate.WorkSurface(sql.NotPredicates(p))
}
